SELECT V.ID, V.TITULO, V.YT_VIDEO_ID, (SELECT COUNT(*) FROM PRATICAS PX WHERE PX.VIDEO_ID = V.ID AND PX.CONSELHO = 0) NP FROM VIDEOS V WHERE V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND V.TITULO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%') ORDER BY V.PUBLICADO_EM DESC LIMIT 15